// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title IAccessControl
 * @dev Interface for Access Control Contract
 * @notice Manages role-based access for hotels and police departments
 */
interface IAccessControl {

    /**
     * @dev Enum for user roles in the system
     */
    enum Role {
        None,           // No role assigned
        HotelStaff,     // Hotel staff member
        HotelManager,   // Hotel manager
        PoliceOfficer,  // Regular police officer
        PoliceAdmin,    // Police department administrator
        SystemAdmin     // System administrator
    }

    /**
     * @dev Struct to store access request information
     */
    struct AccessRequest {
        string requestId;             // Unique request identifier
        address requester;           // Address requesting access
        string guestId;              // Guest ID being accessed
        Role requesterRole;          // Role of the requester
        string purpose;              // Purpose of access request
        uint256 requestTimestamp;    // When request was made
        uint256 expiryTimestamp;     // When request expires
        bool isApproved;             // Whether request is approved
        address[] approvers;         // Addresses that approved the request
        string[] conditions;         // Conditions for access
    }

    /**
     * @dev Struct to store access log entry
     */
    struct AccessLog {
        string logId;                 // Unique log identifier
        address accessor;            // Address that accessed data
        string guestId;              // Guest ID accessed
        uint256 accessTimestamp;     // When access occurred
        string dataAccessed;         // What data was accessed
        bool isAuthorized;           // Whether access was authorized
    }

    /**
     * @dev Event emitted when a role is assigned
     * @param user Address of the user
     * @param role Assigned role
     * @param assignedBy Address that assigned the role
     */
    event RoleAssigned(
        address indexed user,
        uint8 role,
        address indexed assignedBy
    );

    /**
     * @dev Event emitted when a role is revoked
     * @param user Address of the user
     * @param role Revoked role
     * @param revokedBy Address that revoked the role
     */
    event RoleRevoked(
        address indexed user,
        uint8 role,
        address indexed revokedBy
    );

    /**
     * @dev Event emitted when access is granted
     * @param requestId Unique request identifier
     * @param requester Address requesting access
     * @param guestId Guest ID being accessed
     */
    event AccessGranted(
        string indexed requestId,
        address indexed requester,
        string indexed guestId
    );

    /**
     * @dev Event emitted when access is denied
     * @param requestId Unique request identifier
     * @param requester Address requesting access
     * @param guestId Guest ID being accessed
     * @param reason Reason for denial
     */
    event AccessDenied(
        string indexed requestId,
        address indexed requester,
        string indexed guestId,
        string reason
    );

    /**
     * @dev Event emitted when data is accessed
     * @param accessor Address that accessed data
     * @param guestId Guest ID accessed
     * @param timestamp Access timestamp
     */
    event DataAccessed(
        address indexed accessor,
        string indexed guestId,
        uint256 timestamp
    );

    /**
     * @dev Assign a role to a user
     * @param user Address of the user
     * @param role Role to assign
     * @return success Whether role assignment was successful
     */
    function assignRole(
        address user,
        Role role
    ) external returns (bool success);

    /**
     * @dev Revoke a role from a user
     * @param user Address of the user
     * @param role Role to revoke
     * @return success Whether role revocation was successful
     */
    function revokeRole(
        address user,
        Role role
    ) external returns (bool success);

    /**
     * @dev Get the role of a user
     * @param user Address of the user
     * @return role User's role
     */
    function getRole(
        address user
    ) external view returns (Role role);

    /**
     * @dev Check if a user has a specific role
     * @param user Address of the user
     * @param role Role to check
     * @return hasRole Whether user has the specified role
     */
    function hasRole(
        address user,
        Role role
    ) external view returns (bool hasRole);

    /**
     * @dev Request access to guest data
     * @param guestId Guest ID to access
     * @param purpose Purpose of access request
     * @param duration Duration of access in seconds
     * @return requestId Unique request identifier
     */
    function requestAccess(
        string memory guestId,
        string memory purpose,
        uint256 duration
    ) external returns (string memory requestId);

    /**
     * @dev Approve an access request
     * @param requestId Unique request identifier
     * @return success Whether approval was successful
     */
    function approveAccessRequest(
        string memory requestId
    ) external returns (bool success);

    /**
     * @dev Deny an access request
     * @param requestId Unique request identifier
     * @param reason Reason for denial
     * @return success Whether denial was successful
     */
    function denyAccessRequest(
        string memory requestId,
        string memory reason
    ) external returns (bool success);

    /**
     * @dev Check if access is granted for a specific request
     * @param requestId Unique request identifier
     * @return isGranted Whether access is granted
     * @return expiryTimestamp When access expires
     */
    function isAccessGranted(
        string memory requestId
    ) external view returns (
        bool isGranted,
        uint256 expiryTimestamp
    );

    /**
     * @dev Get access request details
     * @param requestId Unique request identifier
     * @return request AccessRequest struct
     */
    function getAccessRequest(
        string memory requestId
    ) external view returns (AccessRequest memory request);

    /**
     * @dev Log data access
     * @param guestId Guest ID accessed
     * @param dataType Type of data accessed
     * @return logId Unique log identifier
     */
    function logDataAccess(
        string memory guestId,
        string memory dataType
    ) external returns (string memory logId);

    /**
     * @dev Get access logs for audit
     * @param guestId Guest ID to filter by (empty string for all)
     * @param startTimestamp Start timestamp for filtering
     * @param endTimestamp End timestamp for filtering
     * @return logs Array of access log entries
     */
    function getAccessLogs(
        string memory guestId,
        uint256 startTimestamp,
        uint256 endTimestamp
    ) external view returns (AccessLog[] memory logs);

    /**
     * @dev Check if current caller can access specific guest data
     * @param guestId Guest ID to check access for
     * @return canAccess Whether access is allowed
     */
    function canAccessGuestData(
        string memory guestId
    ) external view returns (bool canAccess);
}

hotel-police-system/contracts/GuestVerif.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "../interfaces/IGuestVerification.sol";
import "../interfaces/IAccessControl.sol";
import "../interfaces/IDataStorage.sol";

/**
 * @title GuestVerification
 * @dev Main contract for guest verification using Aadhaar and retina scan
 * @notice Implements secure guest identity verification and management
 */
contract GuestVerification is IGuestVerification {

    // Mapping from guestId to GuestBiometricData
    mapping(string => GuestBiometricData) private guestBiometricData;

    // Mapping from guestId to GuestInfo
    mapping(string => GuestInfo) private guestInfo;

    // Mapping from hotel address to list of guest IDs
    mapping(address => string[]) private hotelGuests;

    // Mapping from guestId to hotel address
    mapping(string => address) private guestToHotel;

    // Access control contract reference
    IAccessControl public accessControl;

    // Data storage contract reference
    IDataStorage public dataStorage;

    // Event counters
    uint256 private guestCounter;

    // Modifiers
    modifier onlyHotel() {
        require(
            accessControl.hasRole(msg.sender, IAccessControl.Role.HotelStaff) ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.HotelManager),
            "Only hotel staff can perform this action"
        );
        _;
    }

    modifier onlyVerifiedGuest(string memory _guestId) {
        require(guestExists(_guestId), "Guest does not exist");
        require(guestBiometricData[_guestId].isVerified, "Guest is not verified");
        _;
    }

    /**
     * @dev Constructor to initialize the contract
     * @param _accessControl Address of the AccessControl contract
     * @param _dataStorage Address of the DataStorage contract
     */
    constructor(address _accessControl, address _dataStorage) {
        accessControl = IAccessControl(_accessControl);
        dataStorage = IDataStorage(_dataStorage);
    }

    /**
     * @dev Set the access control contract address
     * @param _accessControl Address of the AccessControl contract
     */
    function setAccessControl(address _accessControl) external {
        require(msg.sender == address(accessControl) || 
                accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
                "Only system admin can set access control");
        accessControl = IAccessControl(_accessControl);
    }

    /**
     * @dev Set the data storage contract address
     * @param _dataStorage Address of the DataStorage contract
     */
    function setDataStorage(address _dataStorage) external {
        require(msg.sender == address(dataStorage) || 
                accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
                "Only system admin can set data storage");
        dataStorage = IDataStorage(_dataStorage);
    }

    /**
     * @dev Verify guest using Aadhaar and retina scan data
     * @param guestId Unique guest identifier
     * @param aadhaarHash IPFS hash of encrypted Aadhaar data
     * @param retinaScanHash IPFS hash of encrypted retina scan
     * @param guestName Guest name
     * @param contactNumber Guest contact number
     * @param roomNumber Room number assigned
     * @return success Whether verification was successful
     */
    function verifyGuest(
        string memory guestId,
        string memory aadhaarHash,
        string memory retinaScanHash,
        string memory guestName,
        string memory contactNumber,
        string memory roomNumber
    ) external override onlyHotel returns (bool success) {
        require(bytes(guestId).length > 0, "Guest ID cannot be empty");
        require(bytes(aadhaarHash).length > 0, "Aadhaar hash cannot be empty");
        require(bytes(retinaScanHash).length > 0, "Retina scan hash cannot be empty");
        require(!guestExists(guestId), "Guest already exists");

        // Store biometric data
        guestBiometricData[guestId] = GuestBiometricData({
            aadhaarHash: aadhaarHash,
            retinaScanHash: retinaScanHash,
            verificationTimestamp: block.timestamp,
            verifiedBy: msg.sender,
            isVerified: true
        });

        // Store guest info
        guestInfo[guestId] = GuestInfo({
            guestId: guestId,
            name: guestName,
            contactNumber: contactNumber,
            roomNumber: roomNumber,
            checkInTime: block.timestamp,
            checkOutTime: 0,
            isActive: true
        });

        // Map guest to hotel
        guestToHotel[guestId] = msg.sender;
        hotelGuests[msg.sender].push(guestId);

        // Store data references in data storage contract
        string memory aadhaarDataId = dataStorage.storeData(
            guestId,
            IDataStorage.DataType.AadhaarData,
            aadhaarHash,
            0, // Size will be updated
            "AES-256",
            "", // Encryption key hash
            30 days // Retention period
        );

        string memory retinaDataId = dataStorage.storeData(
            guestId,
            IDataStorage.DataType.RetinaScan,
            retinaScanHash,
            0, // Size will be updated
            "AES-256",
            "", // Encryption key hash
            30 days // Retention period
        );

        emit GuestVerified(guestId, msg.sender, block.timestamp);

        return true;
    }

    /**
     * @dev Update guest biometric data
     * @param guestId Unique guest identifier
     * @param aadhaarHash New IPFS hash of encrypted Aadhaar data
     * @param retinaScanHash New IPFS hash of encrypted retina scan
     * @return success Whether update was successful
     */
    function updateGuestBiometrics(
        string memory guestId,
        string memory aadhaarHash,
        string memory retinaScanHash
    ) external override onlyHotel onlyVerifiedGuest(guestId) returns (bool success) {
        require(guestToHotel[guestId] == msg.sender, "Only the verifying hotel can update biometrics");

        // Update biometric data
        guestBiometricData[guestId].aadhaarHash = aadhaarHash;
        guestBiometricData[guestId].retinaScanHash = retinaScanHash;
        guestBiometricData[guestId].verificationTimestamp = block.timestamp;
        guestBiometricData[guestId].verifiedBy = msg.sender;

        emit GuestDataUpdated(guestId, msg.sender, block.timestamp);

        return true;
    }

    /**
     * @dev Get guest verification status
     * @param guestId Unique guest identifier
     * @return isVerified Whether guest is verified
     * @return verifiedBy Address that verified the guest
     * @return timestamp Verification timestamp
     */
    function getGuestVerificationStatus(
        string memory guestId
    ) external view override returns (
        bool isVerified,
        address verifiedBy,
        uint256 timestamp
    ) {
        require(guestExists(guestId), "Guest does not exist");

        GuestBiometricData memory data = guestBiometricData[guestId];
        return (data.isVerified, data.verifiedBy, data.verificationTimestamp);
    }

    /**
     * @dev Get guest biometric data references
     * @param guestId Unique guest identifier
     * @return aadhaarHash IPFS hash of encrypted Aadhaar data
     * @return retinaScanHash IPFS hash of encrypted retina scan
     */
    function getGuestBiometricData(
        string memory guestId
    ) external view override returns (
        string memory aadhaarHash,
        string memory retinaScanHash
    ) {
        require(guestExists(guestId), "Guest does not exist");

        GuestBiometricData memory data = guestBiometricData[guestId];
        return (data.aadhaarHash, data.retinaScanHash);
    }

    /**
     * @dev Get complete guest information
     * @param guestId Unique guest identifier
     * @return info GuestInfo struct containing guest details
     */
    function getGuestInfo(
        string memory guestId
    ) external view override returns (GuestInfo memory info) {
        require(guestExists(guestId), "Guest does not exist");
        return guestInfo[guestId];
    }

    /**
     * @dev Check if a guest exists in the system
     * @param guestId Unique guest identifier
     * @return exists Whether guest exists
     */
    function guestExists(
        string memory guestId
    ) public view override returns (bool exists) {
        return bytes(guestInfo[guestId].guestId).length > 0;
    }

    /**
     * @dev Invalidate guest verification (check-out or revocation)
     * @param guestId Unique guest identifier
     * @return success Whether invalidation was successful
     */
    function invalidateGuest(
        string memory guestId
    ) external override onlyHotel onlyVerifiedGuest(guestId) returns (bool success) {
        require(guestToHotel[guestId] == msg.sender, "Only the verifying hotel can invalidate guest");

        // Mark guest as inactive
        guestInfo[guestId].isActive = false;
        guestInfo[guestId].checkOutTime = block.timestamp;

        // Mark biometric data as unverified
        guestBiometricData[guestId].isVerified = false;

        emit GuestDataUpdated(guestId, msg.sender, block.timestamp);

        return true;
    }

    /**
     * @dev Get all guests for a specific hotel
     * @param hotelAddress Address of the hotel
     * @return guestIds Array of guest IDs for the hotel
     */
    function getHotelGuests(
        address hotelAddress
    ) external view returns (string[] memory guestIds) {
        return hotelGuests[hotelAddress];
    }

    /**
     * @dev Get the hotel address for a specific guest
     * @param guestId Unique guest identifier
     * @return hotelAddress Address of the hotel
     */
    function getGuestHotel(
        string memory guestId
    ) external view returns (address hotelAddress) {
        require(guestExists(guestId), "Guest does not exist");
        return guestToHotel[guestId];
    }

    /**
     * @dev Check if a guest is currently active (checked in)
     * @param guestId Unique guest identifier
     * @return isActive Whether guest is active
     */
    function isGuestActive(
        string memory guestId
    ) external view returns (bool isActive) {
        require(guestExists(guestId), "Guest does not exist");
        return guestInfo[guestId].isActive;
    }

    /**
     * @dev Get guest count for a hotel
     * @param hotelAddress Address of the hotel
     * @return count Number of guests for the hotel
     */
    function getHotelGuestCount(
        address hotelAddress
    ) external view returns (uint256 count) {
        return hotelGuests[hotelAddress].length;
    }
}

hotel-police-system/interfaces/IGuestVer.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title IGuestVerification
 * @dev Interface for Guest Verification Contract
 * @notice Provides functions for guest identity verification using Aadhaar and retina scan
 */
interface IGuestVerification {

    /**
     * @dev Struct to store guest biometric data references
     */
    struct GuestBiometricData {
        string aadhaarHash;          // IPFS hash of encrypted Aadhaar data
        string retinaScanHash;       // IPFS hash of encrypted retina scan
        uint256 verificationTimestamp;
        address verifiedBy;          // Hotel address that verified the guest
        bool isVerified;
    }

    /**
     * @dev Struct to store guest information
     */
    struct GuestInfo {
        string guestId;              // Unique guest identifier
        string name;
        string contactNumber;
        string roomNumber;
        uint256 checkInTime;
        uint256 checkOutTime;
        bool isActive;
    }

    /**
     * @dev Event emitted when a guest is verified
     * @param guestId Unique guest identifier
     * @param hotelAddress Address of the hotel
     * @param timestamp Verification timestamp
     */
    event GuestVerified(
        string indexed guestId,
        address indexed hotelAddress,
        uint256 timestamp
    );

    /**
     * @dev Event emitted when guest data is updated
     * @param guestId Unique guest identifier
     * @param updatedBy Address that updated the data
     * @param timestamp Update timestamp
     */
    event GuestDataUpdated(
        string indexed guestId,
        address indexed updatedBy,
        uint256 timestamp
    );

    /**
     * @dev Event emitted when there's a verification failure
     * @param guestId Unique guest identifier
     * @param reason Failure reason
     * @param timestamp Failure timestamp
     */
    event VerificationFailed(
        string indexed guestId,
        string reason,
        uint256 timestamp
    );

    /**
     * @dev Verify guest using Aadhaar and retina scan data
     * @param guestId Unique guest identifier
     * @param aadhaarHash IPFS hash of encrypted Aadhaar data
     * @param retinaScanHash IPFS hash of encrypted retina scan
     * @param guestName Guest name
     * @param contactNumber Guest contact number
     * @param roomNumber Room number assigned
     * @return success Whether verification was successful
     */
    function verifyGuest(
        string memory guestId,
        string memory aadhaarHash,
        string memory retinaScanHash,
        string memory guestName,
        string memory contactNumber,
        string memory roomNumber
    ) external returns (bool success);

    /**
     * @dev Update guest biometric data
     * @param guestId Unique guest identifier
     * @param aadhaarHash New IPFS hash of encrypted Aadhaar data
     * @param retinaScanHash New IPFS hash of encrypted retina scan
     * @return success Whether update was successful
     */
    function updateGuestBiometrics(
        string memory guestId,
        string memory aadhaarHash,
        string memory retinaScanHash
    ) external returns (bool success);

    /**
     * @dev Get guest verification status
     * @param guestId Unique guest identifier
     * @return isVerified Whether guest is verified
     * @return verifiedBy Address that verified the guest
     * @return timestamp Verification timestamp
     */
    function getGuestVerificationStatus(
        string memory guestId
    ) external view returns (
        bool isVerified,
        address verifiedBy,
        uint256 timestamp
    );

    /**
     * @dev Get guest biometric data references
     * @param guestId Unique guest identifier
     * @return aadhaarHash IPFS hash of encrypted Aadhaar data
     * @return retinaScanHash IPFS hash of encrypted retina scan
     */
    function getGuestBiometricData(
        string memory guestId
    ) external view returns (
        string memory aadhaarHash,
        string memory retinaScanHash
    );

    /**
     * @dev Get complete guest information
     * @param guestId Unique guest identifier
     * @return info GuestInfo struct containing guest details
     */
    function getGuestInfo(
        string memory guestId
    ) external view returns (GuestInfo memory info);

    /**
     * @dev Check if a guest exists in the system
     * @param guestId Unique guest identifier
     * @return exists Whether guest exists
     */
    function guestExists(
        string memory guestId
    ) external view returns (bool exists);

    /**
     * @dev Invalidate guest verification (check-out or revocation)
     * @param guestId Unique guest identifier
     * @return success Whether invalidation was successful
     */
    function invalidateGuest(
        string memory guestId
    ) external returns (bool success);
}

hotel-police-system/interfaces/IDataStor.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title IDataStorage
 * @dev Interface for Data Storage Contract
 * @notice Manages secure storage of guest data using IPFS and on-chain hashes
 */
interface IDataStorage {

    /**
     * @dev Enum for data types stored in the system
     */
    enum DataType {
        AadhaarData,      // Aadhaar card information
        RetinaScan,       // Retina scan biometric data
        GuestPhoto,       // Guest photograph
        IdentificationDoc, // Other identification documents
        StayHistory,      // Guest stay history
        EmergencyContact  // Emergency contact information
    }

    /**
     * @dev Struct to store data reference information
     */
    struct DataReference {
        string ipfsHash;           // IPFS hash of the encrypted data
        DataType dataType;        // Type of data stored
        uint256 uploadTimestamp;   // When data was uploaded
        address uploadedBy;        // Address that uploaded the data
        uint256 size;             // Size of the data in bytes
        string encryptionAlgorithm; // Encryption algorithm used
        string encryptionKeyHash; // Hash of the encryption key (stored off-chain)
    }

    /**
     * @dev Struct to store data access metadata
     */
    struct DataMetadata {
        string dataId;             // Unique data identifier
        string guestId;           // Guest ID this data belongs to
        DataType dataType;        // Type of data
        bool isActive;            // Whether data is active/valid
        uint256 retentionPeriod;  // How long data should be retained (seconds)
        uint256 expiryTimestamp;  // When data should be deleted
    }

    /**
     * @dev Event emitted when data is stored
     * @param dataId Unique data identifier
     * @param guestId Guest ID this data belongs to
     * @param dataType Type of data stored
     * @param ipfsHash IPFS hash of the data
     */
    event DataStored(
        string indexed dataId,
        string indexed guestId,
        uint8 dataType,
        string ipfsHash
    );

    /**
     * @dev Event emitted when data is retrieved
     * @param dataId Unique data identifier
     * @param retrievedBy Address that retrieved the data
     * @param timestamp Retrieval timestamp
     */
    event DataRetrieved(
        string indexed dataId,
        address indexed retrievedBy,
        uint256 timestamp
    );

    /**
     * @dev Event emitted when data is deleted
     * @param dataId Unique data identifier
     * @param deletedBy Address that deleted the data
     * @param timestamp Deletion timestamp
     */
    event DataDeleted(
        string indexed dataId,
        address indexed deletedBy,
        uint256 timestamp
    );

    /**
     * @dev Event emitted when data retention is updated
     * @param dataId Unique data identifier
     * @param newRetentionPeriod New retention period in seconds
     * @param updatedBy Address that updated the retention
     */
    event RetentionUpdated(
        string indexed dataId,
        uint256 newRetentionPeriod,
        address indexed updatedBy
    );

    /**
     * @dev Store data reference with IPFS hash
     * @param guestId Guest ID this data belongs to
     * @param dataType Type of data being stored
     * @param ipfsHash IPFS hash of the encrypted data
     * @param size Size of the data in bytes
     * @param encryptionAlgorithm Encryption algorithm used
     * @param encryptionKeyHash Hash of the encryption key
     * @param retentionPeriod How long data should be retained (seconds)
     * @return dataId Unique data identifier
     */
    function storeData(
        string memory guestId,
        DataType dataType,
        string memory ipfsHash,
        uint256 size,
        string memory encryptionAlgorithm,
        string memory encryptionKeyHash,
        uint256 retentionPeriod
    ) external returns (string memory dataId);


    function getDataReference(
        string memory dataId
    ) external view returns (
        DataReference memory DataReference,
        DataMetadata memory metadata
    );

    /**
     * @dev Get all data references for a specific guest
     * @param guestId Guest ID to query
     * @return dataIds Array of data identifiers
     */
    function getGuestDataReferences(
        string memory guestId
    ) external view returns (string[] memory dataIds);

    /**
     * @dev Get data references by type for a guest
     * @param guestId Guest ID to query
     * @param dataType Type of data to filter by
     * @return dataIds Array of data identifiers matching criteria
     */
    function getGuestDataByType(
        string memory guestId,
        DataType dataType
    ) external view returns (string[] memory dataIds);

    /**
     * @dev Delete data reference and mark for cleanup
     * @param dataId Unique data identifier
     * @return success Whether deletion was successful
     */
    function deleteData(
        string memory dataId
    ) external returns (bool success);

    /**
     * @dev Update retention period for data
     * @param dataId Unique data identifier
     * @param newRetentionPeriod New retention period in seconds
     * @return success Whether update was successful
     */
    function updateRetention(
        string memory dataId,
        uint256 newRetentionPeriod
    ) external returns (bool success);

    /**
     * @dev Check if data exists
     * @param dataId Unique data identifier
     * @return exists Whether data exists
     */
    function dataExists(
        string memory dataId
    ) external view returns (bool exists);

    /**
     * @dev Check if data has expired and should be deleted
     * @param dataId Unique data identifier
     * @return isExpired Whether data has expired
     */
    function isDataExpired(
        string memory dataId
    ) external view returns (bool isExpired);

    /**
     * @dev Verify data integrity by checking hash
     * @param dataId Unique data identifier
     * @param expectedHash Expected IPFS hash
     * @return isValid Whether data integrity is valid
     */
    function verifyDataIntegrity(
        string memory dataId,
        string memory expectedHash
    ) external view returns (bool isValid);

    /**
     * @dev Get the IPFS hash for a specific data ID
     * @param dataId Unique data identifier
     * @return ipfsHash IPFS hash of the data
     */
    function getIPFSHash(
        string memory dataId
    ) external view returns (string memory ipfsHash);
}

hotel-police-system/contracts/DataStorag.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "../interfaces/IDataStorage.sol";
import "../interfaces/IAccessControl.sol";

/**
 * @title DataStorage
 * @dev Main contract for secure data storage using IPFS
 * @notice Manages encrypted data storage with on-chain hashes and metadata
 */
contract DataStorage is IDataStorage {

    // Mapping from dataId to DataReference
    mapping(string => DataReference) private dataReferences;

    // Mapping from dataId to DataMetadata
    mapping(string => DataMetadata) private dataMetadata;

    // Mapping from guestId to array of dataIds
    mapping(string => string[]) private guestData;

    // Mapping from (guestId, dataType) to array of dataIds
    mapping(string => mapping(uint8 => string[])) private guestDataByType;

    // Access control contract reference
    IAccessControl public accessControl;

    // Event counters
    uint256 private dataCounter;

    // Default retention period (30 days)
    uint256 public defaultRetentionPeriod = 30 days;

    // Modifiers
    modifier onlyAuthorized() {
        require(
            accessControl.hasRole(msg.sender, IAccessControl.Role.HotelStaff) ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.HotelManager) ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.PoliceOfficer) ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.PoliceAdmin) ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
            "Only authorized personnel can perform this action"
        );
        _;
    }

    /**
     * @dev Constructor to initialize the contract
     * @param _accessControl Address of the AccessControl contract
     */
    constructor(address _accessControl) {
        accessControl = IAccessControl(_accessControl);
    }

    /**
     * @dev Set the access control contract address
     * @param _accessControl Address of the AccessControl contract
     */
    function setAccessControl(address _accessControl) external {
        require(
            msg.sender == address(accessControl) ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
            "Only system admin can set access control"
        );
        accessControl = IAccessControl(_accessControl);
    }

    /**
     * @dev Store data reference with IPFS hash
     * @param guestId Guest ID this data belongs to
     * @param dataType Type of data being stored
     * @param ipfsHash IPFS hash of the encrypted data
     * @param size Size of the data in bytes
     * @param encryptionAlgorithm Encryption algorithm used
     * @param encryptionKeyHash Hash of the encryption key
     * @param retentionPeriod How long data should be retained (seconds)
     * @return dataId Unique data identifier
     */
    function storeData(
        string memory guestId,
        DataType dataType,
        string memory ipfsHash,
        uint256 size,
        string memory encryptionAlgorithm,
        string memory encryptionKeyHash,
        uint256 retentionPeriod
    ) external override onlyAuthorized returns (string memory dataId) {
        require(bytes(guestId).length > 0, "Guest ID cannot be empty");
        require(bytes(ipfsHash).length > 0, "IPFS hash cannot be empty");
        require(size > 0, "Data size must be positive");
        require(bytes(encryptionAlgorithm).length > 0, "Encryption algorithm cannot be empty");

        // Generate unique data ID
        dataCounter++;
        dataId = _generateDataId(dataCounter);

        // Set retention period
        if (retentionPeriod == 0) {
            retentionPeriod = defaultRetentionPeriod;
        }

        uint256 expiryTimestamp = block.timestamp + retentionPeriod;

        // Store data reference
        dataReferences[dataId] = DataReference({
            ipfsHash: ipfsHash,
            dataType: dataType,
            uploadTimestamp: block.timestamp,
            uploadedBy: msg.sender,
            size: size,
            encryptionAlgorithm: encryptionAlgorithm,
            encryptionKeyHash: encryptionKeyHash
        });

        // Store metadata
        dataMetadata[dataId] = DataMetadata({
            dataId: dataId,
            guestId: guestId,
            dataType: dataType,
            isActive: true,
            retentionPeriod: retentionPeriod,
            expiryTimestamp: expiryTimestamp
        });

        // Add to guest data mappings
        guestData[guestId].push(dataId);
        guestDataByType[guestId][uint8(dataType)].push(dataId);

        emit DataStored(dataId, guestId, uint8(dataType), ipfsHash);

        return dataId;
    }

    /**
     * @dev Retrieve data reference information
     * @param dataId Unique data identifier
     * @return dataRef DataReference struct
     * @return metadata DataMetadata struct
     */
    function getDataReference(
        string memory dataId
    ) external view override returns (
        DataReference memory dataRef,
        DataMetadata memory metadata
    ) {
        require(dataExists(dataId), "Data does not exist");
        return (dataReferences[dataId], dataMetadata[dataId]);
    }

    /**
     * @dev Get all data references for a specific guest
     * @param guestId Guest ID to query
     * @return dataIds Array of data identifiers
     */
    function getGuestDataReferences(
        string memory guestId
    ) external view override returns (string[] memory dataIds) {
        return guestData[guestId];
    }

    /**
     * @dev Get data references by type for a guest
     * @param guestId Guest ID to query
     * @param dataType Type of data to filter by
     * @return dataIds Array of data identifiers matching criteria
     */
 function getGuestDataByType(
    string memory guestId,
    DataType dataType
) external view override returns (string[] memory) {
    return guestDataByType[guestId][uint8(dataType)];
}

    /**
     * @dev Delete data reference and mark for cleanup
     * @param dataId Unique data identifier
     * @return success Whether deletion was successful
     */
    function deleteData(
        string memory dataId
    ) external override onlyAuthorized returns (bool success) {
        require(dataExists(dataId), "Data does not exist");

        DataMetadata storage metadata = dataMetadata[dataId];

        // Check if caller is authorized to delete this data
        require(
            msg.sender == dataReferences[dataId].uploadedBy ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
            "Only uploader or system admin can delete data"
        );

        // Mark as inactive
        metadata.isActive = false;
        metadata.expiryTimestamp = block.timestamp;

        emit DataDeleted(dataId, msg.sender, block.timestamp);

        return true;
    }

    /**
     * @dev Update retention period for data
     * @param dataId Unique data identifier
     * @param newRetentionPeriod New retention period in seconds
     * @return success Whether update was successful
     */
    function updateRetention(
        string memory dataId,
        uint256 newRetentionPeriod
    ) external override onlyAuthorized returns (bool success) {
        require(dataExists(dataId), "Data does not exist");
        require(newRetentionPeriod > 0, "Retention period must be positive");

        DataMetadata storage metadata = dataMetadata[dataId];

        // Check if caller is authorized to update retention
        require(
            msg.sender == dataReferences[dataId].uploadedBy ||
            accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
            "Only uploader or system admin can update retention"
        );

        uint256 oldExpiry = metadata.expiryTimestamp;
        metadata.retentionPeriod = newRetentionPeriod;
        metadata.expiryTimestamp = block.timestamp + newRetentionPeriod;

        emit RetentionUpdated(dataId, newRetentionPeriod, msg.sender);

        return true;
    }

    /**
     * @dev Check if data exists
     * @param dataId Unique data identifier
     * @return exists Whether data exists
     */
    function dataExists(
        string memory dataId
    ) public view override returns (bool exists) {
        return bytes(dataReferences[dataId].ipfsHash).length > 0;
    }

    /**
     * @dev Check if data has expired and should be deleted
     * @param dataId Unique data identifier
     * @return isExpired Whether data has expired
     */
    function isDataExpired(
        string memory dataId
    ) external view override returns (bool isExpired) {
        require(dataExists(dataId), "Data does not exist");
        return block.timestamp >= dataMetadata[dataId].expiryTimestamp;
    }

    /**
     * @dev Verify data integrity by checking hash
     * @param dataId Unique data identifier
     * @param expectedHash Expected IPFS hash
     * @return isValid Whether data integrity is valid
     */
    function verifyDataIntegrity(
        string memory dataId,
        string memory expectedHash
    ) external view override returns (bool isValid) {
        require(dataExists(dataId), "Data does not exist");
        return keccak256(bytes(dataReferences[dataId].ipfsHash)) == keccak256(bytes(expectedHash));
    }

    /**
     * @dev Get the IPFS hash for a specific data ID
     * @param dataId Unique data identifier
     * @return ipfsHash IPFS hash of the data
     */
    function getIPFSHash(
        string memory dataId
    ) external view override returns (string memory ipfsHash) {
        require(dataExists(dataId), "Data does not exist");
        return dataReferences[dataId].ipfsHash;
    }

  /**
 * @dev Get all data IDs for a specific guest
 * @param guestId Unique guest identifier
 * @return dataIds Array of data identifiers
 */
function getDataIdsByGuest(string memory guestId) public view returns (string[] memory) {
    // Replace with your logic to fetch data IDs for the guest
    return new string[](0); // Temporary placeholder
}

/**
 * @dev Get data IDs for a specific guest by data type
 * @param guestId Unique guest identifier
 * @param dataType Type of data to retrieve
 * @return dataIds Array of data identifiers
 */
function getDataIdsByGuestAndType(
    string memory guestId,
    string memory dataType
) external view returns (string[] memory) {
    // Get all data IDs for the guest
    string[] memory allDataIds = getDataIdsByGuest(guestId);
    string[] memory filteredDataIds = new string[](allDataIds.length);
    uint256 filteredCount = 0;

    // Filter data IDs by type (replace with your logic)
    for (uint256 i = 0; i < allDataIds.length; i++) {
        // Example: Check if data type matches (replace with your logic)
        if (/* condition to check data type */ true) {
            filteredDataIds[filteredCount] = allDataIds[i];
            filteredCount++;
        }
    }

    // Resize the array to the actual filtered count
    assembly {
        mstore(filteredDataIds, filteredCount)
    }

    return filteredDataIds;
}

function getExpiredData() external view returns (string[] memory) {
    uint256 counter = 0;
    return new string[](0);
}
    /**
     * @dev Set default retention period
     * @param _defaultRetentionPeriod New default retention period in seconds
     */
    function setDefaultRetentionPeriod(
        uint256 _defaultRetentionPeriod
    ) external {
        require(
            accessControl.hasRole(msg.sender, IAccessControl.Role.SystemAdmin),
            "Only system admin can set default retention period"
        );
        require(_defaultRetentionPeriod > 0, "Retention period must be positive");
        defaultRetentionPeriod = _defaultRetentionPeriod;
    }

    /**
     * @dev Internal function to generate data ID
     * @param counter Counter value
     * @return dataId Generated data ID
     */
    function _generateDataId(uint256 counter) internal pure returns (string memory) {
        return string(abi.encodePacked("DATA-", _uint2str(counter)));
    }

    /**
     * @dev Internal function to convert uint to string
     * @param value Value to convert
     * @return str String representation
     */
    function _uint2str(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 j = value;
        uint256 length;
        while (j != 0) {
            length++;
            j /= 10;
        }
        bytes memory buffer = new bytes(length);
        while (value != 0) {
            length--;
            buffer[length] = bytes1(uint8(48 + value % 10));
            value /= 10;
        }
        return string(buffer);
    }
}

